base='https://www.reading.ac.uk/ready-to-study/study/Fees-and-funding/scholarships/'
tw='https://www.reading.ac.uk/ready-to-study/international-and-eu/country-specific-information/country-specific-taiwan'
mie='https://mieconnect.com/scholarships?institution=university-of-reading'
