 extra=dict(status=t('開放中','Open'),eligibilityTW=t('可申請（須符合下列條件）','Eligible subject to conditions'),verificationDate=D,featuredDate=D,featuredUntil='2026-11-10T00:00:00+08:00',reviewExpiresAt='2026-11-15T00:00:00+08:00',country=t('英國','United Kingdom'),level=t(*x['level']),funding=t(*x['funding']),deadline=t(*x['deadline']),officialUrl=base+x['tail'],secondSourceUrl=x['second'],sourceName='University of Reading',sourceType=t('大學官方','University official'),taiwanNote=t(desc,de))
 a=write(x['key'],x['slug'],x['title'],x['en'],desc,de,x['paras'],sources,'award',extra);assert a['slug'] not in r['scholarshipBaselineSlugs'];a.update(isNew=True,baselineAbsent=True,eligibleTaiwan=True,open=True,updateSummary='New distinct award; official current cycle, Taiwan admissions and external catalogue checked. Scope and unpublished conditions disclosed.');aw.append(a)
